  return state;
}

coding.referenceSolution:
function cart(state, action) {
  if (action.type === "add") {
    if (state.some((l) => l.id === action.id)) {
      return state.map((l) => (l.id === action.id ? { ...l, qty: l.qty + 1 } : l));
