function history(state, action) {
  if (action.type === "set") {
    return { past: [...state.past, state.present], present: action.value, future: state.future };
  }
  if (action.type === "undo") {
    const prev = state.past[state.past.length - 1];
    return { past: state.past.slice(0, -1), present: prev, future: [state.present, ...state.future] };
  }
  return state;
}

coding.referenceSolution:
function history(state, action) {
  if (action.type === "set") {
    return { past: [...state.past, state.present], present: action.value, future: [] };
  }
  if (action.type === "undo") {
    if (!state.past.length) return state;
    const prev = state.past[state.past.length - 1];
    return { past: state.past.slice(0, -1), present: prev, future: [state.present, ...state.future] };
  }
  if (action.type === "redo") {
    if (!state.future.length) return state;
    const [next, ...rest] = state.future;
    return { past: [...state.past, state.present], present: next, future: rest };
  }
  return state;
}

