function resolveRoute(routes, path) {
  for (const r of routes) {
    if (r.path === path) return { name: r.name, params: {} };
  }
  return null;
}

coding.referenceSolution:
function resolveRoute(routes, path) {
  const segs = path.split("/").filter(Boolean);
  for (const r of routes) {
    if (r.path === "/:pathMatch(.*)*") return { name: r.name, params: {} };
    const p = r.path.split("/").filter(Boolean);
    if (p.length !== segs.length) continue;
    const params = {};
    let ok = true;
    for (let i = 0; i < p.length; i++) {
      if (p[i].startsWith(":")) params[p[i].slice(1)] = segs[i];
      else if (p[i] !== segs[i]) { ok = false; break; }
    }
    if (ok) return { name: r.name, params };
  }
  return null;
}

