type Todo = { id: number; title: string; done: boolean };
type Action =
  | { type: "toggle"; id: number }
  | { type: "rollback"; id: number; previous: Todo }
  | { type: "confirm"; id: number; todo: Todo };

function todos(state: Todo[], action: Action): Todo[] {
  if (action.type === "toggle") {
    return state.map((t) => (t.id === action.id ? { ...t, done: !t.done } : t));
  }
  return state;
}

coding.referenceSolution:
type Todo = { id: number; title: string; done: boolean };
type Action =
  | { type: "toggle"; id: number }
  | { type: "rollback"; id: number; previous: Todo }
  | { type: "confirm"; id: number; todo: Todo };

function todos(state: Todo[], action: Action): Todo[] {
  switch (action.type) {
    case "toggle":
      return state.map((t) => (t.id === action.id ? { ...t, done: !t.done } : t));
    case "rollback":
      return state.map((t) => (t.id === action.id ? action.previous : t));
    case "confirm":
      return state.map((t) => (t.id === action.id ? action.todo : t));
    default:
      return state;
  }
}

