function formErrors(values: Record<string, string>, rules: Record<string, string[]>): Record<string, string> {
  const errors: Record<string, string> = {};
  for (const field of Object.keys(rules)) {
    const v = values[field] ?? "";
    for (const rule of rules[field]) {
      if (rule === "required" && !v.trim()) errors[field] = "Required";
      if (rule === "email" && !/^\S+@\S+\.\S+$/.test(v)) errors[field] = "Invalid email";
    }
  }
  return errors;
}

coding.referenceSolution:
function formErrors(values: Record<string, string>, rules: Record<string, string[]>): Record<string, string> {
  const errors: Record<string, string> = {};
  for (const field of Object.keys(rules)) {
    const v = (values[field] ?? "").trim();
    for (const rule of rules[field]) {
      let msg: string | null = null;
      if (rule === "required" && !v) msg = "Required";
      else if (rule === "email" && v && !/^\S+@\S+\.\S+$/.test(v)) msg = "Invalid email";
      else if (rule.startsWith("min:")) {
        const n = Number(rule.slice(4));
        if (v && v.length < n) msg = `At least ${n} characters`;
      }
      if (msg) {
        errors[field] = msg;
        break;
      }
    }
  }
  return errors;
}

