function keepAliveCache(visits, max) {
  const cache = [];
  for (const v of visits) {
    if (!cache.includes(v)) cache.push(v);
    if (cache.length > max) cache.shift();
  }
  return cache;
}

coding.referenceSolution:
function keepAliveCache(visits, max) {
  const cache = [];
  for (const v of visits) {
    const i = cache.indexOf(v);
    if (i >= 0) cache.splice(i, 1);
    cache.push(v);
    if (cache.length > max) cache.shift();
  }
  return cache;
}

