coding.referenceSolution:
function mergeQuery(current, patch) {
  const merged = { ...current, ...patch };
  const out = {};
  for (const [k, v] of Object.entries(merged)) {
    if (v === null || v === undefined || v === "") continue;
    if (Array.isArray(v) && v.length === 0) continue;
    out[k] = v;
  }
  return out;
}
